<?php
namespace Database\Seeders;
use App\Models\{InventoryItem,MenuCategory,MenuItem,MenuModifier,Outlet,Property,Recipe,RestaurantTable};use Illuminate\Database\Seeder;
class HotelPosSeeder extends Seeder{public function run():void{$property=Property::firstOrFail();$restaurant=Outlet::firstOrCreate(['property_id'=>$property->id,'code'=>'REST'],['name'=>'Main Restaurant','type'=>'restaurant','location'=>'Ground Floor','uses_tables'=>true,'uses_kitchen'=>true,'is_active'=>true]);$bar=Outlet::firstOrCreate(['property_id'=>$property->id,'code'=>'BAR'],['name'=>'Main Bar','type'=>'bar','location'=>'Lobby','uses_tables'=>true,'uses_kitchen'=>true,'is_active'=>true]);foreach(range(1,12) as $n)RestaurantTable::firstOrCreate(['outlet_id'=>$restaurant->id,'name'=>'Table '.$n],['property_id'=>$property->id,'section'=>$n<=6?'Main Hall':'Terrace','capacity'=>4,'status'=>'available','display_order'=>$n,'is_active'=>true]);foreach(range(1,6) as $n)RestaurantTable::firstOrCreate(['outlet_id'=>$bar->id,'name'=>'Bar '.$n],['property_id'=>$property->id,'section'=>'Bar','capacity'=>4,'status'=>'available','display_order'=>$n,'is_active'=>true]);$rice=InventoryItem::firstOrCreate(['property_id'=>$property->id,'sku'=>'ING-RICE'],['name'=>'Rice','category'=>'Dry Goods','kind'=>'ingredient','unit'=>'kg','quantity_on_hand'=>20,'reorder_level'=>5,'average_cost'=>5000,'is_active'=>true]);$chicken=InventoryItem::firstOrCreate(['property_id'=>$property->id,'sku'=>'ING-CHICKEN'],['name'=>'Chicken','category'=>'Meat','kind'=>'ingredient','unit'=>'kg','quantity_on_hand'=>15,'reorder_level'=>4,'average_cost'=>16000,'is_active'=>true]);$beer=InventoryItem::firstOrCreate(['property_id'=>$property->id,'sku'=>'BEV-BEER'],['name'=>'Local Beer 500ml','category'=>'Beer','kind'=>'beverage','unit'=>'bottle','quantity_on_hand'=>120,'reorder_level'=>24,'average_cost'=>3500,'is_active'=>true]);$whisky=InventoryItem::firstOrCreate(['property_id'=>$property->id,'sku'=>'BEV-WHISKY'],['name'=>'Whisky 750ml','category'=>'Spirits','kind'=>'beverage','unit'=>'bottle','quantity_on_hand'=>12,'reorder_level'=>3,'average_cost'=>65000,'is_active'=>true]);$main=MenuCategory::firstOrCreate(['property_id'=>$property->id,'outlet_id'=>$restaurant->id,'name'=>'Main Course'],['display_order'=>10,'is_active'=>true]);$drinks=MenuCategory::firstOrCreate(['property_id'=>$property->id,'outlet_id'=>$bar->id,'name'=>'Drinks'],['display_order'=>10,'is_active'=>true]);$food=MenuItem::firstOrCreate(['property_id'=>$property->id,'outlet_id'=>$restaurant->id,'name'=>'Chicken & Rice'],['menu_category_id'=>$main->id,'sku'=>'FOOD-001','price'=>35000,'tax_rate'=>0,'service_charge_rate'=>0,'send_to_kitchen'=>true,'is_bar_item'=>false,'is_active'=>true]);$recipe=Recipe::firstOrCreate(['menu_item_id'=>$food->id],['property_id'=>$property->id,'name'=>'Chicken & Rice Standard','yield_quantity'=>1]);$recipe->ingredients()->updateOrCreate(['inventory_item_id'=>$chicken->id],['quantity'=>0.30]);$recipe->ingredients()->updateOrCreate(['inventory_item_id'=>$rice->id],['quantity'=>0.25]);MenuItem::firstOrCreate(['property_id'=>$property->id,'outlet_id'=>$bar->id,'name'=>'Local Beer'],['menu_category_id'=>$drinks->id,'inventory_item_id'=>$beer->id,'sku'=>'BAR-001','price'=>8000,'stock_quantity_per_sale'=>1,'send_to_kitchen'=>false,'is_bar_item'=>true,'is_active'=>true]);MenuItem::firstOrCreate(['property_id'=>$property->id,'outlet_id'=>$bar->id,'name'=>'Whisky Shot'],['menu_category_id'=>$drinks->id,'inventory_item_id'=>$whisky->id,'sku'=>'BAR-002','price'=>12000,'stock_quantity_per_sale'=>0.04,'send_to_kitchen'=>false,'is_bar_item'=>true,'is_active'=>true]);MenuModifier::firstOrCreate(['property_id'=>$property->id,'name'=>'Extra Chips'],['price_delta'=>5000,'is_active'=>true]);MenuModifier::firstOrCreate(['property_id'=>$property->id,'name'=>'No Onions'],['price_delta'=>0,'is_active'=>true]);}}
